import type { ColumnDef, SortingState } from "@tanstack/react-table";

export type DataTableConfig<T> = {
  key: string;
  columns: Array<ColumnDef<T>>;
  initialSorting?: SortingState;
  enabled?: boolean;
  metadata?: Record<string, unknown>;
};

export function createDataTableConfig<T>(config: DataTableConfig<T>) {
  return {
    key: config.key,
    columns: config.columns,
    initialSorting: config.initialSorting ?? [],
    enabled: config.enabled ?? true,
    metadata: config.metadata ?? {},
  };
}

export const dataTableChecks = [
  "Resolve rows with tenant-scoped server queries",
  "Authorize row-level actions separately from table visibility",
  "Record audit events for sensitive row operations",
] as const;

import {
  flexRender,
  getCoreRowModel,
  useReactTable,
  type ColumnDef,
  type SortingState,
} from "@tanstack/react-table";
import { useState } from "react";

export function StackFoundryDataTable<T>({
  rows,
  columns,
  empty = "No records found.",
}: {
  rows: Array<T & { id: string }>;
  columns: Array<ColumnDef<T>>;
  empty?: string;
}) {
  const [sorting, setSorting] = useState<SortingState>([]);
  const table = useReactTable({
    data: rows,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
  });

  if (rows.length === 0) {
    return <div className="rounded-lg border p-6 text-sm text-muted-foreground">{empty}</div>;
  }

  return (
    <div className="overflow-x-auto rounded-lg border">
      <table className="w-full text-sm">
        <thead>
          {table.getHeaderGroups().map((headerGroup) => (
            <tr key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <th key={header.id} className="p-3 text-left">
                  {header.column.getCanSort() ? (
                    <button type="button" onClick={header.column.getToggleSortingHandler()}>
                      {flexRender(header.column.columnDef.header, header.getContext())}
                      {{ asc: " ↑", desc: " ↓" }[header.column.getIsSorted() as string] ?? ""}
                    </button>
                  ) : (
                    flexRender(header.column.columnDef.header, header.getContext())
                  )}
                </th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody>
          {table.getRowModel().rows.map((row) => (
            <tr key={row.id} className="border-t">
              {row.getVisibleCells().map((cell) => (
                <td key={cell.id} className="p-3">
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import { StackFoundryDataTable } from "@/components/stackfoundry/data-table";

const rows = [
  { id: "1", name: "Acme", plan: "Pro", requests: "842,500" },
  { id: "2", name: "Globex", plan: "Team", requests: "128,300" },
];

const columns = [
  { accessorKey: "name", header: "Workspace" },
  { accessorKey: "plan", header: "Plan" },
  { accessorKey: "requests", header: "API requests" },
];

export default function DataTableDemo() {
  return <StackFoundryDataTable rows={rows} columns={columns} />;
}
